%solving diff equation generated using bond graph technique

clc
clear

%initial conditions
x0=[80 0]; %Initial condition for momentum and displacement

timespan = [0 10]; %0 to 10s

[t,x]= ode45(@InClassOct8,timespan,x0);

plot(t,x(:,2)) %[output:5604e6c0]
xlabel('Time(s)') %[output:5604e6c0]
ylabel('Displacement(m)') %[output:5604e6c0]
title('Displacement vs Time');

plot(t,x(:,1)) %[output:06a37987]
xlabel('Time(s)')
ylabel('Displacement(m)')
title('Displacement vs Time');

